1|// Figure placement and picture request rules for one scene. Pure:
2|// no React, no DOM, no network. scene-page.tsx owns the DOM side
3|// (setPage, scroll, pulse) and use-pictures.ts owns the requests.
4|export function groupFiguresByEndN<F extends { endN: number }>(figures: F[]): Map<number, F[]> {
5|  const grouped = new Map<number, F[]>();
6|  for (const fig of figures) {
7|    const list = grouped.get(fig.endN) ?? [];
8|    list.push(fig);
9|    grouped.set(fig.endN, list);
10|  }
11|  return grouped;
