14|// Figures to render after paragraph i of the visible sub-page: only when
15|// it is the last visible fragment of its ordinal on this page. Each page
16|// renders after its own last visible fragment, so a paragraph split
17|// across two pages shows its figures on both.
18|export function figuresAfter<P extends { n: number }, F>(
19|  paragraphs: P[],
20|  i: number,
21|  grouped: Map<number, F[]>,
22|): F[] {
23|  const cur = paragraphs[i];
24|  if (!cur) return [];
25|  return paragraphs[i + 1]?.n !== cur.n ? (grouped.get(cur.n) ?? []) : [];
26|}
