28|// Index of the sub-page holding paragraph ordinal n, -1 when none.
29|export function pageOfOrdinal<P extends { n: number }>(pages: { paragraphs: P[] }[], n: number): number {
30|  return pages.findIndex((p) => p.paragraphs.some((para) => para.n === n));
31|}
